const COMPONENT_TYPES = ['rune', 'moonstone'];
const BLOCK_SIZE = 3;
const BLOCK_PREMIUM = 60;

function isComponent(type: string): boolean {
  return COMPONENT_TYPES.includes(type);
}

function basePremiumOfPolicy(items: Item[]): number {
  const mainTotal = items
    .filter((item) => !isComponent(item.type))
    .reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);

  const counts = new Map<string, number>();
  for (const item of items.filter((i) => isComponent(i.type))) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }

  let componentTotal = 0;
  for (const [type, count] of counts) {
    componentTotal +=
      count === BLOCK_SIZE ? BLOCK_PREMIUM : count * BASE_PREMIUMS[type];
  }

  return mainTotal + componentTotal;
}

export function runScenario(scenario: Scenario): ScenarioResult {
  return {
    results: scenario.steps.map((step) => ({
      premium: basePremiumOfPolicy(step.items) + PROCESSING_FEE,
    })),
  };
}

