export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: 'quote';
  items: Item[];
}

export type Step = QuoteStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface QuoteResult {
  premium: number;
}

export type StepResult = QuoteResult;

export interface ScenarioResult {
  results: StepResult[];
}

const PROCESSING_FEE = 5;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const COMPONENT_TYPES = ['rune', 'moonstone'];
const BLOCK_SIZE = 3;
const BLOCK_PREMIUM = 60;

function isComponent(type: string): boolean {
  return COMPONENT_TYPES.includes(type);
}

const CURSE_SURCHARGE = 0.5;
const HIGH_ENCHANTMENT_LEVEL = 5;
const HIGH_ENCHANTMENT_SURCHARGE = 0.3;

function itemSurchargeRate(item: Item): number {
  let rate = 0;
  if (item.cursed) rate += CURSE_SURCHARGE;
  if ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL) {
    rate += HIGH_ENCHANTMENT_SURCHARGE;
  }
  return rate;
}

function itemBasePremiums(items: Item[]): { item: Item; base: number }[] {
  const componentCounts = new Map<string, number>();
  for (const item of items.filter((i) => isComponent(i.type))) {
    componentCounts.set(item.type, (componentCounts.get(item.type) ?? 0) + 1);
  }

  return items.map((item) => {
    if (!isComponent(item.type)) {
      return { item, base: BASE_PREMIUMS[item.type] };
    }
    const count = componentCounts.get(item.type) ?? 0;
    const base =
      count === BLOCK_SIZE
        ? BLOCK_PREMIUM / BLOCK_SIZE
        : BASE_PREMIUMS[item.type];
    return { item, base };
  });
}

const LOYALTY_YEARS = 2;
const LOYALTY_DISCOUNT = 0.2;

function basePremiumOfPolicy(items: Item[]): number {
  return itemBasePremiums(items).reduce((sum, { base }) => sum + base, 0);
}

function itemSurchargesOfPolicy(items: Item[]): number {
  return itemBasePremiums(items).reduce(
    (sum, { item, base }) => sum + base * itemSurchargeRate(item),
    0,
  );
}

function premiumOf(items: Item[], customer: Customer): number {
  const base = basePremiumOfPolicy(items);
  const loyalty =
    customer.yearsWithMHPCO >= LOYALTY_YEARS ? base * LOYALTY_DISCOUNT : 0;

  return Math.ceil(
    base + itemSurchargesOfPolicy(items) - loyalty + PROCESSING_FEE,
  );
}

export function runScenario(scenario: Scenario): ScenarioResult {
  return {
    results: scenario.steps.map((step) => ({
      premium: premiumOf(step.items, scenario.customer),
    })),
  };
}

