const INSURANCE_VALUES: Record<string, number> = {
  sword: 1000,
  amulet: 600,
  staff: 800,
  potion: 400,
  rune: 250,
  moonstone: 250,
};

const DEDUCTIBLE = 100;
const CAP_FACTOR = 2;

interface Policy {
  items: Item[];
  remainingCap: number;
}

function payoutFor(damage: Damage): number {
  return Math.max(0, damage.amount - DEDUCTIBLE);
}

function settle(policy: Policy, incident: Incident): ClaimResult {
  const desired = incident.damages.reduce(
    (sum, damage) => sum + payoutFor(damage),
    0,
  );
  const payout = Math.floor(Math.min(desired, policy.remainingCap));
  policy.remainingCap -= payout;

  return { payout, remainingCap: policy.remainingCap };
}

export function runScenario(scenario: Scenario): ScenarioResult {
  let contracts = 0;
  const policies = new Map<number, Policy>();

  return {
    results: scenario.steps.map((step, index) => {
      if (step.op === 'quote') {
        const premium = premiumOf(step.items, scenario.customer, contracts);
        contracts += 1;
        policies.set(index, {
          items: step.items,
          remainingCap:
            CAP_FACTOR *
            step.items.reduce(
              (sum, item) => sum + INSURANCE_VALUES[item.type],
              0,
            ),
        });
        return { premium };
      }

      return settle(policies.get(step.policy)!, step.incident);
    }),
  };
}

