50	
51	export interface ScenarioResult {
52	  results: StepResult[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	
57	const BASE_PREMIUMS: Record<string, number> = {
58	  sword: 100,
59	  amulet: 60,
60	  staff: 80,
61	  potion: 40,
62	  rune: 25,
63	  moonstone: 25,
64	};
65	
66	const COMPONENT_TYPES = ['rune', 'moonstone'];
67	const BLOCK_SIZE = 3;
68	const BLOCK_PREMIUM = 60;
69	
70	function isComponent(type: string): boolean {
71	  return COMPONENT_TYPES.includes(type);
72	}
73	
74	const CURSE_SURCHARGE = 0.5;
75	const HIGH_ENCHANTMENT_LEVEL = 5;
76	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
77	
78	function itemSurchargeRate(item: Item): number {
79	  let rate = 0;
80	  if (item.cursed) rate += CURSE_SURCHARGE;
81	  if ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL) {
82	    rate += HIGH_ENCHANTMENT_SURCHARGE;
83	  }
84	  return rate;
85	}
86	
87	function itemBasePremiums(items: Item[]): { item: Item; base: number }[] {
88	  for (const item of items) {
89	    if (!(item.type in BASE_PREMIUMS)) {
90	      throw new Error(`unknown item type: ${item.type}`);
91	    }
92	  }
93	
94	  const componentCounts = new Map<string, number>();
95	  for (const item of items.filter((i) => isComponent(i.type))) {
96	    componentCounts.set(item.type, (componentCounts.get(item.type) ?? 0) + 1);
97	  }
98	
99	  return items.map((item) => {
100	    if (!isComponent(item.type)) {
101	      return { item, base: BASE_PREMIUMS[item.type] };
102	    }
103	    const count = componentCounts.get(item.type) ?? 0;
104	    const base =
105	      count === BLOCK_SIZE
106	        ? BLOCK_PREMIUM / BLOCK_SIZE
107	        : BASE_PREMIUMS[item.type];
108	    return { item, base };
109	  });
110	}
111	
112	const LOYALTY_YEARS = 2;
113	const LOYALTY_DISCOUNT = 0.2;
114	const FIRST_INSURANCE_SURCHARGE = 0.1;
115	const FOLLOW_UP_DISCOUNT = 0.15;
116	
117	function basePremiumOfPolicy(items: Item[]): number {
118	  return itemBasePremiums(items).reduce((sum, { base }) => sum + base, 0);
119	}
120	
121	function itemSurchargesOfPolicy(items: Item[]): number {
122	  return itemBasePremiums(items).reduce(
123	    (sum, { item, base }) => sum + base * itemSurchargeRate(item),
124	    0,
125	  );
126	}
127	
128	function premiumOf(
129	  items: Item[],
130	  customer: Customer,
131	  previousContracts: number,
132	): number {
133	  const base = basePremiumOfPolicy(items);
134	  const loyalty =
135	    customer.yearsWithMHPCO >= LOYALTY_YEARS ? base * LOYALTY_DISCOUNT : 0;
136	  const followUp = previousContracts > 0 ? base * FOLLOW_UP_DISCOUNT : 0;
137	
138	  return Math.ceil(
139	    base +
140	      itemSurchargesOfPolicy(items) -
141	      loyalty -
142	      followUp +
143	      base * FIRST_INSURANCE_SURCHARGE +
144	      PROCESSING_FEE,
145	  );
146	}
147	
148	const INSURANCE_VALUES: Record<string, number> = {
149	  sword: 1000,
150	  amulet: 600,
151	  staff: 800,
152	  potion: 400,
153	  rune: 250,
154	  moonstone: 250,
155	};
156	
157	const DEDUCTIBLE = 100;
158	const CAP_FACTOR = 2;
159	const REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
160	const REDUCED_REIMBURSEMENT = 0.5;
161	
162	interface Policy {
163	  items: Item[];
164	  remainingCap: number;
165	}
166	
167	function reimbursementRate(item: Item): number {
168	  return (item.enchantment ?? 0) >= REIMBURSEMENT_ENCHANTMENT_LEVEL
169	    ? REDUCED_REIMBURSEMENT
170	    : 1;
171	}
172	
173	function payoutFor(damage: Damage, item: Item): number {
174	  return Math.max(0, damage.amount * reimbursementRate(item) - DEDUCTIBLE);
175	}
176	
177	function settle(policy: Policy, incident: Incident): ClaimResult {
178	  const available = [...policy.items];
179	  const desired = incident.damages.reduce((sum, damage) => {
180	    if (damage.amount < 0) {
181	      throw new Error(`negative damage amount: ${damage.amount}`);
182	    }
183	    const index = available.findIndex((item) => item.type === damage.itemType);
184	    if (index === -1) {
185	      throw new Error(`item not covered by the policy: ${damage.itemType}`);
186	    }
187	    const item = available.splice(index, 1)[0];
188	    return sum + payoutFor(damage, item);
189	  }, 0);
190	
191	  const payout = Math.floor(Math.min(desired, policy.remainingCap));
192	  policy.remainingCap -= payout;
193	
194	  return { payout, remainingCap: policy.remainingCap };
195	}
196	
197	export function runScenario(scenario: Scenario): ScenarioResult {
198	  let contracts = 0;
199	  const policies = new Map<number, Policy>();
